import sys

sys.setrecursionlimit(200000)

class MinHeap:
    def __init__(self):
        self.heap = []

    def _parent(self, i):
        return (i - 1) // 2

    def _left(self, i):
        return 2 * i + 1

    def _right(self, i):
        return 2 * i + 2

    def _sift_up(self, i):
        if i <= 0:
            return
        p = self._parent(i)
        if self.heap[i] < self.heap[p]:
            self.heap[i], self.heap[p] = self.heap[p], self.heap[i]
            self._sift_up(p)

    def _sift_down(self, i):
        n = len(self.heap)
        smallest = i
        l = self._left(i)
        r = self._right(i)

        if l < n and self.heap[l] < self.heap[smallest]:
            smallest = l
        if r < n and self.heap[r] < self.heap[smallest]:
            smallest = r

        if smallest != i:
            self.heap[i], self.heap[smallest] = self.heap[smallest], self.heap[i]
            self._sift_down(smallest)

    def push(self, val):
        self.heap.append(val)
        self._sift_up(len(self.heap) - 1)

    def extract_min(self):
        if not self.heap:
            return -1
        min_val = self.heap[0]
        last = self.heap.pop()
        if self.heap:
            self.heap[0] = last
            self._sift_down(0)
        return min_val

    def peek(self):
        if not self.heap:
            return -1
        return self.heap[0]

    def size(self):
        return len(self.heap)

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    Q = int(input_data[0])
    idx = 1
    heap = MinHeap()
    out = []

    for _ in range(Q):
        op = int(input_data[idx])
        idx += 1
        if op == 1:
            val = int(input_data[idx])
            idx += 1
            heap.push(val)
        elif op == 2:
            out.append(str(heap.extract_min()))
        elif op == 3:
            out.append(str(heap.peek()))
        elif op == 4:
            out.append(str(heap.size()))

    sys.stdout.write('\n'.join(out) + '\n')

if __name__ == '__main__':
    solve()

