import java.io.*;
import java.util.*;

public class Main {
    static class MinHeap {
        private ArrayList<Long> heap = new ArrayList<>();

        private void siftUp(int i) {
            if (i <= 0) return;
            int p = (i - 1) / 2;
            if (heap.get(i) < heap.get(p)) {
                long temp = heap.get(i);
                heap.set(i, heap.get(p));
                heap.set(p, temp);
                siftUp(p);
            }
        }

        private void siftDown(int i) {
            int n = heap.size();
            int smallest = i;
            int l = 2 * i + 1;
            int r = 2 * i + 2;

            if (l < n && heap.get(l) < heap.get(smallest)) smallest = l;
            if (r < n && heap.get(r) < heap.get(smallest)) smallest = r;

            if (smallest != i) {
                long temp = heap.get(i);
                heap.set(i, heap.get(smallest));
                heap.set(smallest, temp);
                siftDown(smallest);
            }
        }

        public void push(long val) {
            heap.add(val);
            siftUp(heap.size() - 1);
        }

        public long extractMin() {
            if (heap.isEmpty()) return -1;
            long minVal = heap.get(0);
            long last = heap.remove(heap.size() - 1);
            if (!heap.isEmpty()) {
                heap.set(0, last);
                siftDown(0);
            }
            return minVal;
        }

        public long peek() {
            if (heap.isEmpty()) return -1;
            return heap.get(0);
        }

        public int size() {
            return heap.size();
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        while (line != null && line.trim().isEmpty()) line = br.readLine();
        if (line == null) return;
        int Q = Integer.parseInt(line.trim());

        MinHeap heap = new MinHeap();
        StringBuilder sb = new StringBuilder();
        StringTokenizer st = null;

        for (int i = 0; i < Q; i++) {
            while (st == null || !st.hasMoreTokens()) {
                line = br.readLine();
                if (line == null) break;
                st = new StringTokenizer(line);
            }
            if (st == null || !st.hasMoreTokens()) break;
            int op = Integer.parseInt(st.nextToken());
            if (op == 1) {
                long val = Long.parseLong(st.nextToken());
                heap.push(val);
            } else if (op == 2) {
                sb.append(heap.extractMin()).append("\n");
            } else if (op == 3) {
                sb.append(heap.peek()).append("\n");
            } else if (op == 4) {
                sb.append(heap.size()).append("\n");
            }
        }
        System.out.print(sb.toString());
    }
}

