using namespace std;

class MinHeap {
    vector<long long> heap;

    void sift_up(int i) {
        if (i <= 0) return;
        int p = (i - 1) / 2;
        if (heap[i] < heap[p]) {
            swap(heap[i], heap[p]);
            sift_up(p);
        }
    }

    void sift_down(int i) {
        int n = heap.size();
        int smallest = i;
        int l = 2 * i + 1;
        int r = 2 * i + 2;

        if (l < n && heap[l] < heap[smallest]) smallest = l;
        if (r < n && heap[r] < heap[smallest]) smallest = r;

        if (smallest != i) {
            swap(heap[i], heap[smallest]);
            sift_down(smallest);
        }
    }

public:
    void push(long long val) {
        heap.push_back(val);
        sift_up((int)heap.size() - 1);
    }

    long long extract_min() {
        if (heap.empty()) return -1;
        long long min_val = heap[0];
        long long last = heap.back();
        heap.pop_back();
        if (!heap.empty()) {
            heap[0] = last;
            sift_down(0);
        }
        return min_val;
    }

    long long peek() {
        if (heap.empty()) return -1;
        return heap[0];
    }

    int size() {
        return (int)heap.size();
    }
};

