def solve():
    raw = sys.stdin.read().split()
    if not raw:
        return
    N = int(raw[0])
    K = int(raw[1])
    arr = [int(x) for x in raw[2:2+N]]

    dq = deque() # stores indices
    res = []

    for i in range(N):
        while dq and dq[0] <= i - K:
            dq.popleft()
        while dq and arr[dq[-1]] <= arr[i]:
            dq.pop()
        dq.append(i)

        if i >= K - 1:
            res.append(arr[dq[0]])

    print(*(res))

