import java.io.*;
import java.util.*;

public class Main {
    static class Node implements Comparable<Node> {
        long val;
        int r, c;
        Node(long val, int r, int c) {
            this.val = val;
            this.r = r;
            this.c = c;
        }
        public int compareTo(Node o) {
            return Long.compare(this.val, o.val);
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        while (line != null && line.trim().isEmpty()) line = br.readLine();
        if (line == null) return;
        StringTokenizer st = new StringTokenizer(line);
        int K = Integer.parseInt(st.nextToken());
        int N = Integer.parseInt(st.nextToken());

        long[][] arrays = new long[K][N];
        for (int i = 0; i < K; i++) {
            st = new StringTokenizer(br.readLine());
            for (int j = 0; j < N; j++) {
                arrays[i][j] = Long.parseLong(st.nextToken());
            }
        }

        PriorityQueue<Node> pq = new PriorityQueue<>();
        for (int i = 0; i < K; i++) {
            if (N > 0) pq.add(new Node(arrays[i][0], i, 0));
        }

        StringBuilder sb = new StringBuilder();
        int count = 0;
        while (!pq.isEmpty()) {
            Node cur = pq.poll();
            if (count++ > 0) sb.append(" ");
            sb.append(cur.val);
            if (cur.c + 1 < N) {
                pq.add(new Node(arrays[cur.r][cur.c + 1], cur.r, cur.c + 1));
            }
        }
        System.out.println(sb.toString());
    }
}

