    for (int i = 0; i < N; i++) cin >> merged[i];
    for (int i = 0; i < M; i++) cin >> merged[N + i];

    int total = N + M;
    for (int i = total / 2 - 1; i >= 0; i--) {
        heapify(merged, total, i);
    }

