import sys
import heapq
import math

def solve():
    raw = sys.stdin.read().split()
    if not raw:
        return
    N = int(raw[0])

    max_heap = [] # stores smaller half as negative numbers
    min_heap = [] # stores larger half
    out = []

    for i in range(1, N + 1):
        x = int(raw[i])

        # Step 1: Add to appropriate heap
        if not max_heap or x <= -max_heap[0]:
            heapq.heappush(max_heap, -x)
        else:
            heapq.heappush(min_heap, x)

        # Step 2: Rebalance heaps so len(max_heap) == len(min_heap) or len(max_heap) == len(min_heap) + 1
        if len(max_heap) > len(min_heap) + 1:
            heapq.heappush(min_heap, -heapq.heappop(max_heap))
        elif len(min_heap) > len(max_heap):
            heapq.heappush(max_heap, -heapq.heappop(min_heap))

        # Step 3: Compute median
        if len(max_heap) > len(min_heap):
            med = -max_heap[0]
        else:
            med = math.floor((-max_heap[0] + min_heap[0]) / 2)

        out.append(str(med))

    sys.stdout.write('\n'.join(out) + '\n')

if __name__ == '__main__':
    solve()

