    }

    static Node buildTree(long[] vals) {
        if (vals.length == 0 || vals[0] == -1) return null;
        Node root = new Node(vals[0]);
        ArrayDeque<Node> q = new ArrayDeque<>();
        q.add(root);
        int idx = 1;
        int n = vals.length;

        while (!q.isEmpty() && idx < n) {
            Node cur = q.poll();
            if (idx < n) {
                if (vals[idx] != -1) {
                    cur.left = new Node(vals[idx]);
                    q.add(cur.left);
                }
                idx++;
            }
            if (idx < n) {
                if (vals[idx] != -1) {
                    cur.right = new Node(vals[idx]);
                    q.add(cur.right);
                }
                idx++;
            }
        }
        return root;
    }

    static boolean isHeap(Node root) {
        if (root == null) return true;
        ArrayDeque<Node> q = new ArrayDeque<>();
        q.add(root);
        boolean seenNull = false;

        while (!q.isEmpty()) {
            Node cur = q.poll();

            if (cur.left != null) {
                if (seenNull) return false;
                if (cur.left.val > cur.val) return false;
                q.add(cur.left);
            } else {
                seenNull = true;
