def build_tree(vals):
    if not vals or vals[0] == -1:
        return None
    root = Node(vals[0])
    q = deque([root])
    idx = 1
    n = len(vals)

    while q and idx < n:
        cur = q.popleft()
        if idx < n:
            if vals[idx] != -1:
                cur.left = Node(vals[idx])
                q.append(cur.left)
            idx += 1
        if idx < n:
            if vals[idx] != -1:
                cur.right = Node(vals[idx])
                q.append(cur.right)
            idx += 1
    return root

