public class Main {
    static String addStrings(StringBuilder s1, StringBuilder s2) {
        int i = s1.length() - 1;
        int j = s2.length() - 1;
        int carry = 0;
        StringBuilder res = new StringBuilder();

        while (i >= 0 || j >= 0 || carry > 0) {
            int d1 = (i >= 0) ? (s1.charAt(i) - '0') : 0;
            int d2 = (j >= 0) ? (s2.charAt(j) - '0') : 0;
            int total = d1 + d2 + carry;
            res.append(total % 10);
            carry = total / 10;
            i--;
            j--;
        }

        res.reverse();
        int start = 0;
        while (start < res.length() - 1 && res.charAt(start) == '0') {
            start++;
        }
        return res.substring(start);
    }

    public static void main(String[] args) throws IOException {
